sections.code:
// URL (most common for consumer)
https://example.com/product/8901234

// UPI payment (India-specific)
upi://pay?pa=merchant@bank&pn=Merchant&am=100&cu=INR

// Wi-Fi credentials
WIFI:S:MyNetwork;T:WPA;P:Passw0rd;;

// Contact card (vCard)
BEGIN:VCARD
VERSION:4.0
FN:Ada Lovelace
ORG:GS1 India
END:VCARD

// GS1 element string (rare — pharma prefers DataMatrix)
]Q301089012345678951726010110BATCH99\u001D21SERIAL42

// GS1 Digital Link (consumer + Sunrise 2027)
https://id.gs1.org/01/08901234567895/10/BATCH99/21/SERIAL42?17=260101

// Generate:
//   pubspec.yaml: qr_flutter: ^4.1.0
import 'package:qr_flutter/qr_flutter.dart';

QrImageView(
  data: 'https://id.gs1.org/01/08901234567895',
  size: 200,
  errorCorrectionLevel: QrErrorCorrectLevel.M,
  embeddedImage: const AssetImage('assets/logo.png'),
  embeddedImageStyle: const QrEmbeddedImageStyle(size: Size(40, 40)),
);

// Scan:
//   mobile_scanner already covers QR — restrict formats: [BarcodeFormat.qrCode]

// Detect QR type + route:
void onQrDetect(String raw) {
  if (raw.startsWith('upi://')) {
    // UPI payment intent
    launchUrl(Uri.parse(raw));
  } else if (raw.startsWith('WIFI:')) {
    // Parse Wi-Fi credentials
  } else if (raw.startsWith('https://id.gs1.org/')) {
    // GS1 Digital Link
    _handleDigitalLink(raw);
  } else if (raw.startsWith('https://')) {
    // Generic URL — show destination BEFORE opening (phishing defense)
    _confirmUrlDialog(raw);
  } else {
    // Plain text or GS1 element string
  }
}
